# Validate deterministic coverage before composing.
start, end = date(2026,11,1), date(2026,12,31)
expected = [(start + timedelta(days=i)).isoformat() for i in range((end-start).days+1)]
byday = {d: [] for d in expected}
for x in E:
    if x['day'] not in byday:
        raise ValueError(f'Unexpected date: {x["day"]}')
    byday[x['day']].append(x)
missing = [d for d, rows in byday.items() if len(rows) != 2]
if missing:
    raise ValueError(f'Each day needs exactly two items; invalid dates: {missing}')
if len(weekly) != 9:
    raise ValueError('Expected 9 weekly packages')

lines = []
lines += [
'# Morrison Insurance — Late-Year Social Content Calendar',
'',
'**Planning window:** November 1–December 31, 2026  ',
'**Channels:** paired Facebook + Instagram daily; two separate Google Business Profile (GBP) Update candidates and two LinkedIn candidates each week  ',
'**Status:** Review-ready only — not scheduled or published',
'',
'> **Scheduling control — applies to every planned row.** Confirm Metricool capacity immediately before scheduling, record the approved temporary November–December placement exception, and complete final source/rights review on the posting day. A routine row becomes “scheduled” only after those checks. No automatic email, no non-Morrison destination, no Martinsville school coverage, no legacy-post edits, and no automatic scheduling of regular entries.',
'',
'## Setup and operating rules',
'',
'- **Community-first standard.** Every item is warm, plain-spoken, useful, nonpolitical, and non-salesy. It contains no insurance jargon, product language, price, coverage, claim, response-time, or outcome promise. No fear tactics or pressure-based CTA.',
'- **Cadence.** Each daily entry is one paired Facebook/Instagram placement. The temporary late-year exception permits **two pairs per day**; it does not authorize duplication, filler, automatic scheduling, or publication. Each pair includes a low-friction prompt and 3–5 local/subject hashtags.',
'- **Only narrow automatic-publication exceptions.** A **new qualifying official NWS Shelby County/Center warning** may use the approved Facebook/Instagram warning workflow. The **Thursday 10:00 AM Central Toledo Bend Facebook/Instagram item** may use the approved factual workflow only after its same-day source gate passes. No GBP, LinkedIn, email, website, or other item auto-publishes.',
'- **Conditional means conditional.** “If,” “only if,” and “conditional” items must be replaced or held when the live official source does not confirm them. Time-sensitive facts, local events, road/weather/alert information, outdoor rules, lake conditions, burn restrictions, charity needs, and hours require the stated posting-day gate. Never turn an old screenshot, search snippet, or unchanged status into news.',
'- **Visual and rights standard.** Use only Morrison-owned, original, organizer-approved, or documented permission-cleared imagery. Do not use stock-image direction, downloaded government/organizer art, unapproved AI art, identifiable children/patrons/clients, weapons, harvested animals, private-property identifiers, license plates, or unconsented community photos. GBP requires a real Morrison or recognizable local photo.',
'- **Website links.** No Morrison website resource link is proposed in this calendar because no genuinely relevant published Morrison resource URL was supplied or verified. Add one only after the team confirms it is current, approved, and directly answers the post question; never invent a URL.',
'- **Channel separation.** GBP Update body copy below contains no URL or phone number and is not Facebook copy. LinkedIn candidates are professional and community-oriented, must be posted manually unless the follower rule is formally changed, and are not Facebook duplicates.',
'',
'## Weekly calendar',
''
]

# Mapping dates to weekly package
ranges = [
('Week 1 | November 1–8','2026-11-01','2026-11-08'),
('Week 2 | November 9–15','2026-11-09','2026-11-15'),
('Week 3 | November 16–22','2026-11-16','2026-11-22'),
('Week 4 | November 23–29','2026-11-23','2026-11-29'),
('Week 5 | November 30–December 6','2026-11-30','2026-12-06'),
('Week 6 | December 7–13','2026-12-07','2026-12-13'),
('Week 7 | December 14–20','2026-12-14','2026-12-20'),
('Week 8 | December 21–27','2026-12-21','2026-12-27'),
('Week 9 | December 28–31','2026-12-28','2026-12-31'),
]

for index, (heading, first, last) in enumerate(ranges):
    lines += [f'### {heading}', '', f'**Week status:** `REVIEW-READY — NOT SCHEDULED`. Metricool capacity and every stated source/recheck gate must be confirmed immediately before scheduling.', '', '#### Paired Facebook + Instagram posts', '']
    curr = date.fromisoformat(first)
    stop = date.fromisoformat(last)
    while curr <= stop:
        daylabel = curr.strftime('%A, %B %-d, %Y')
        lines += [f'##### {daylabel}', '']
        for item in byday[curr.isoformat()]:
            lines += [
                f'**{item["slot"]} — {item["title"]}**',
                f'- **Format:** {item["fmt"]}.',
                f'- **Authentic visual direction:** {item["visual"]}',
                f'- **Source / recheck gate:** {item["gate"]}',
                f'- **Engagement prompt:** {item["prompt"]}',
                f'- **Hashtags:** {item["tags"]}',
                f'- **Facebook copy:** {item["fb"]}',
                f'- **Instagram copy:** {item["ig"]}',
                ''
            ]
        curr += timedelta(days=1)
    _, gbp, li = weekly[index]
    lines += ['#### Google Business Profile Update candidates', '', '> **GBP control:** Informational Update only; manual review and Metricool capacity confirmation required. Body copy below intentionally contains **no URL and no phone number**. Use a real local/Morrison photo and a built-in button only after approval.', '']
    for title, body, req in gbp:
        lines += [f'**{title}**', f'- **Body copy:** {body}', f'- **Real local-photo / review requirement:** {req}', '']
    lines += ['#### LinkedIn candidates', '', '> **LinkedIn control:** Manual posting only unless the follower rule is formally changed. Final source, visual-rights, and professional-review check remains required; never use these as automatic cross-posts.', '']
    for title, body, req in li:
        lines += [f'**{title}**', f'- **Candidate copy:** {body}', f'- **Posting requirement:** {req}', '']

lines += ['## References', '', 'All citations identify the official or primary source used for the stated source/recheck gate. Open the live source again on the posting day whenever the calendar calls for a recheck.', '']
for label, url in refs:
    lines.append(f'- {label}: {url}')
lines.append('')
OUT.write_text('\n'.join(lines), encoding='utf-8')
print(f'Wrote {OUT}')
print(f'Daily paired items: {len(E)} across {len(byday)} dates')
print(f'Weekly GBP candidates: {len(weekly)*2}; LinkedIn candidates: {len(weekly)*2}')
print(f'Lines: {len(lines)}; bytes: {OUT.stat().st_size}')
